package com.sergec.feedermonitor;
import android.app.*;import android.os.*;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;import java.net.*;import java.io.*;import java.time.*;import java.time.format.*;import java.util.*;import java.util.concurrent.*;import org.json.*;
public class MainActivity extends Activity{
 static final int BG=Color.rgb(7,17,31),PANEL=Color.rgb(18,32,51),BLUE=Color.rgb(34,166,242),MUTED=Color.rgb(148,163,184),GREEN=Color.rgb(49,211,139),AMBER=Color.rgb(255,186,73),RED=Color.rgb(255,91,104);
 Handler h=new Handler(Looper.getMainLooper());ExecutorService ex=Executors.newSingleThreadExecutor();Random rnd=new Random();LinearLayout body,nav;TextView subtitle;Switch liveSwitch;JSONArray feeders=new JSONArray();ArrayList<Double> history=new ArrayList<>();int page=0;boolean busy=false;String source="DEMO DATA";
 String[] names={"Noodle Line 1","Noodle Line 2","Culinary","Powder","Packaging 1","Packaging 2","Boiler House","Compressors","Water Plant","Cold Store","Warehouse","Industrial Services"};
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(BG);setContentView(shell());generate();render();loop.run();}
 View shell(){LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(BG);LinearLayout head=new LinearLayout(this);head.setOrientation(LinearLayout.VERTICAL);head.setPadding(dp(18),dp(18),dp(18),dp(12));head.addView(txt("FACTORY ENERGY",12,BLUE,true));head.addView(txt("Main Feeder Monitor",26,Color.WHITE,true));subtitle=txt("12 feeders • Demo data",12,MUTED,false);head.addView(subtitle);root.addView(head);ScrollView scroll=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(dp(16),dp(8),dp(16),dp(18));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));nav=new LinearLayout(this);nav.setPadding(dp(4),dp(6),dp(4),dp(8));nav.setBackgroundColor(Color.rgb(11,24,40));String[] n={"Dashboard","Feeders","Alarms","Trends","Settings"};for(int i=0;i<n.length;i++){final int x=i;Button b=new Button(this);b.setText(n[i]);b.setTextSize(10);b.setAllCaps(false);b.setTextColor(i==0?BLUE:MUTED);b.setBackgroundColor(Color.TRANSPARENT);b.setOnClickListener(v->{page=x;render();});nav.addView(b,new LinearLayout.LayoutParams(0,dp(52),1));}root.addView(nav);return root;}
 Runnable loop=new Runnable(){public void run(){if(liveSwitch!=null&&liveSwitch.isChecked())api();else{generate();source="DEMO DATA";render();}h.postDelayed(this,5000);}};
 void generate(){feeders=new JSONArray();double total=0;for(int i=0;i<12;i++){try{JSONObject j=new JSONObject();String st=rnd.nextDouble()<.06?"ALARM":rnd.nextDouble()<.12?"WARNING":"NORMAL";double kw=st.equals("ALARM")?380+rnd.nextDouble()*100:90+rnd.nextDouble()*280;j.put("id",i+1);j.put("name",names[i]);j.put("status",st);j.put("kw",kw);j.put("voltage",408+rnd.nextDouble()*14);j.put("current",kw*1000/(Math.sqrt(3)*415*.93));j.put("power_factor",.88+rnd.nextDouble()*.11);j.put("energy_kwh",1800+rnd.nextDouble()*9000);feeders.put(j);total+=kw;}catch(Exception ignored){}}history.add(total);if(history.size()>12)history.remove(0);}
 void api(){if(busy)return;busy=true;ex.execute(()->{try{HttpURLConnection c=(HttpURLConnection)new URL(BuildConfig.FEEDER_API_URL).openConnection();c.setConnectTimeout(5000);c.setReadTimeout(5000);c.setRequestProperty("Accept","application/json");if(c.getResponseCode()/100!=2)throw new Exception("HTTP "+c.getResponseCode());BufferedReader r=new BufferedReader(new InputStreamReader(c.getInputStream()));StringBuilder b=new StringBuilder();String s;while((s=r.readLine())!=null)b.append(s);JSONObject root=new JSONObject(b.toString());JSONArray a=root.getJSONArray("feeders");if(a.length()!=12)throw new Exception("Expected 12 feeders");feeders=a;source="DJANGO API";runOnUiThread(this::render);}catch(Exception e){generate();source="DEMO FALLBACK";runOnUiThread(this::render);}finally{busy=false;}});}
 void render(){body.removeAllViews();for(int i=0;i<nav.getChildCount();i++)((Button)nav.getChildAt(i)).setTextColor(i==page?BLUE:MUTED);subtitle.setText("12 feeders • "+source);if(page==0)dashboard();else if(page==1)feederPage();else if(page==2)alarms();else if(page==3)trends();else settings();}
 void dashboard(){double kw=0,pf=0,en=0;int alarms=0,online=0;for(int i=0;i<feeders.length();i++){JSONObject j=feeders.optJSONObject(i);kw+=j.optDouble("kw");pf+=j.optDouble("power_factor");en+=j.optDouble("energy_kwh");if(!j.optString("status").equals("OFFLINE"))online++;if(j.optString("status").matches("ALARM|WARNING"))alarms++;}body.addView(hero("TOTAL FACTORY DEMAND",String.format(Locale.US,"%.2f MW",kw/1000),"Live aggregate across 12 feeders",BLUE));LinearLayout row=new LinearLayout(this);row.addView(kpi("ONLINE",online+" / 12",GREEN),new LinearLayout.LayoutParams(0,dp(115),1));row.addView(kpi("ALARMS",String.valueOf(alarms),alarms>0?RED:GREEN),new LinearLayout.LayoutParams(0,dp(115),1));body.addView(row);body.addView(hero("AVERAGE POWER FACTOR",String.format(Locale.US,"%.3f",pf/12),"Target operating efficiency",GREEN));body.addView(hero("ACCUMULATED ENERGY",String.format(Locale.US,"%.0f kWh",en),"Sum of feeder meter readings",Color.WHITE));body.addView(section("FEEDER LOAD OVERVIEW"));for(int i=0;i<feeders.length();i++){JSONObject j=feeders.optJSONObject(i);body.addView(compact(j));}}
 void feederPage(){body.addView(section("ALL MAIN FEEDERS"));for(int i=0;i<feeders.length();i++)body.addView(full(feeders.optJSONObject(i)));}
 void alarms(){body.addView(section("ACTIVE CONDITIONS"));int n=0;for(int i=0;i<feeders.length();i++){JSONObject j=feeders.optJSONObject(i);String st=j.optString("status");if(!st.equals("NORMAL")){n++;LinearLayout c=card();c.addView(txt(st+" • "+j.optString("name"),16,st.equals("ALARM")?RED:AMBER,true));c.addView(txt(String.format(Locale.US,"%.1f kW  •  %.1f V  •  PF %.3f",j.optDouble("kw"),j.optDouble("voltage"),j.optDouble("power_factor")),13,MUTED,false));body.addView(c);}}if(n==0)body.addView(hero("SYSTEM STATUS","ALL NORMAL","No active feeder warnings",GREEN));}
 void trends(){body.addView(section("RECENT TOTAL DEMAND"));double max=1;for(double v:history)max=Math.max(max,v);for(int i=0;i<history.size();i++){double v=history.get(i);LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.addView(txt(String.format(Locale.US,"T-%02d",history.size()-1-i),11,MUTED,false),new LinearLayout.LayoutParams(dp(42),dp(28)));TextView bar=txt(String.format(Locale.US,"  %.2f MW",v/1000),12,Color.WHITE,true);bar.setGravity(Gravity.CENTER_VERTICAL);bar.setBackgroundColor(BLUE);row.addView(bar,new LinearLayout.LayoutParams((int)(dp(250)*v/max),dp(24)));body.addView(row);}body.addView(hero("PEAK IN VIEW",String.format(Locale.US,"%.2f MW",max/1000),"On-device demonstration trend",AMBER));}
 void settings(){body.addView(section("DATA CONNECTION"));liveSwitch=new Switch(this);liveSwitch.setText("Use live Django API");liveSwitch.setTextColor(Color.WHITE);liveSwitch.setTextSize(16);liveSwitch.setChecked(source.equals("DJANGO API"));body.addView(liveSwitch);body.addView(hero("CURRENT SOURCE",source,"Refresh interval: 5 seconds",source.equals("DJANGO API")?GREEN:AMBER));body.addView(hero("CONFIGURED ENDPOINT",BuildConfig.FEEDER_API_URL,"Edit in app/build.gradle.kts",Color.WHITE));body.addView(section("STATUS COLOURS"));body.addView(txt("● NORMAL     ● WARNING     ● ALARM",14,Color.WHITE,true));body.addView(txt("Green indicates normal operation. Amber is a warning. Red requires attention. Grey represents offline communications.",13,MUTED,false));}
 View compact(JSONObject j){LinearLayout r=card();r.setOrientation(LinearLayout.HORIZONTAL);TextView n=txt(j.optString("name"),14,Color.WHITE,true);r.addView(n,new LinearLayout.LayoutParams(0,-2,1));r.addView(txt(String.format(Locale.US,"%.0f kW",j.optDouble("kw")),14,state(j),true));return r;}
 View full(JSONObject j){LinearLayout c=card();LinearLayout top=new LinearLayout(this);top.addView(txt(j.optString("name"),17,Color.WHITE,true),new LinearLayout.LayoutParams(0,-2,1));top.addView(txt(j.optString("status"),12,state(j),true));c.addView(top);c.addView(txt(String.format(Locale.US,"%.1f kW",j.optDouble("kw")),28,BLUE,true));c.addView(txt(String.format(Locale.US,"%.1f V   •   %.1f A   •   PF %.3f",j.optDouble("voltage"),j.optDouble("current"),j.optDouble("power_factor")),13,MUTED,false));c.addView(txt(String.format(Locale.US,"Energy %.0f kWh",j.optDouble("energy_kwh")),12,MUTED,false));return c;}
 int state(JSONObject j){String s=j.optString("status");return s.equals("NORMAL")?GREEN:s.equals("WARNING")?AMBER:s.equals("ALARM")?RED:MUTED;}
 LinearLayout card(){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(16),dp(14),dp(16),dp(14));GradientDrawable g=new GradientDrawable();g.setColor(PANEL);g.setCornerRadius(dp(14));c.setBackground(g);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,0,0,dp(10));c.setLayoutParams(p);return c;}
 View hero(String a,String b,String c,int col){LinearLayout x=card();x.addView(txt(a,11,MUTED,true));x.addView(txt(b,30,col,true));x.addView(txt(c,12,MUTED,false));return x;}View kpi(String a,String b,int col){LinearLayout x=card();x.addView(txt(a,11,MUTED,true));x.addView(txt(b,25,col,true));return x;}TextView section(String s){TextView v=txt(s,12,MUTED,true);v.setPadding(0,dp(12),0,dp(10));return v;}TextView txt(String s,int z,int c,boolean bold){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(c);if(bold)v.setTypeface(null,1);return v;}int dp(int x){return Math.round(x*getResources().getDisplayMetrics().density);}protected void onDestroy(){h.removeCallbacks(loop);ex.shutdownNow();super.onDestroy();}}
